text:
{
  "recommendations": [
    {
      "rec_id": "r1",
      "rationale": [
        {
          "text": "NIR transmission is preferred for transparent or semi-transparent liquids such as whey.",
          "claim_type": "AFS",
          "evidence_ids": ["S01-p18-nir-transmission-clear"]
        },
        {
          "text": "NIR transmission or transflection probes are listed for liquid and colloidal samples.",
          "claim_type": "AFS",
          "evidence_ids": ["TABLE-nir_transmission_or_transflection_probe"]
        }
      ],
      "conditions": [
        {
          "text": "Confirm adequate light transmission through representative whey samples at the proposed optical path.",
          "claim_type": "PROPOSAL",
          "evidence_ids": []
        }
      ],
      "limitations": [
        {
          "text": "Overlapping NIR bands require chemometric calibration for quantitative analysis.",
          "claim_type": "AFS",
          "evidence_ids": ["S01-p10-nir-chemometrics"]
        }
      ]
    },
    {
      "rec_id": "r2",
      "rationale": [
        {
          "text": "In-line NIR reflection is used for opaque or highly concentrated dairy products, including whole milk concentrates.",
          "claim_type": "AFS",
          "evidence_ids": ["S01-p17-nir-reflection-opaque"]
        }
      ],
      "conditions": [],
      "limitations": [
        {
          "text": "NIR reflection is sensitive to surface characteristics and fat globule size.",
          "claim_type": "AFS",
          "evidence_ids": ["S01-p17-reflection-surface"]
        }
      ]
    },
    {
      "rec_id": "r3",
      "rationale": [
        {
          "text": "NIR diffuse reflection probes are listed for scattering media.",
          "claim_type": "AFS",
          "evidence_ids": ["TABLE-nir_diffuse_reflection_probe"]
        }
      ],
      "conditions": [
        {
          "text": "Retain diffuse reflection as an option for the whey only if sample tests demonstrate a usable diffuse-reflection signal.",
          "claim_type": "PROPOSAL",
          "evidence_ids": []
        }
      ],
      "limitations": []
    },
    {
      "rec_id": "r4",
      "rationale": [
        {
          "text": "A transflection probe can sometimes provide a combined solution for low-fat and high-fat milk products.",
          "claim_type": "AFS",
          "evidence_ids": ["S01-p18-transflection-combined"]
        }
      ],
      "conditions": [
        {
          "text": "Retain transmission or transflection for the concentrate only if sample tests demonstrate adequate light penetration.",
          "claim_type": "PROPOSAL",
          "evidence_ids": []
        }
      ],
      "limitations": [
        {
          "text": "Transmission fails when milk becomes too thick or fat-rich for light to penetrate.",
          "claim_type": "AFS",
          "evidence_ids": ["S01-p18-transmission-fails-thick"]
        }
      ]
    }
  ],
  "premise_checks": [],
  "direct_answer": [
    {
      "text": "Compare NIR transmission or transflection with NIR diffuse reflection separately for each stream.",
      "claim_type": "PROPOSAL",
      "evidence_ids": []
    },
    {
      "text": "Pair spectra from representative samples with laboratory protein and fat results where relevant.",
      "claim_type": "PROPOSAL",
      "evidence_ids": []
    },
    {
      "text": "Make the installation choice conditional on validating the resulting calibrations on independent samples against agreed acceptance criteria.",
      "claim_type": "PROPOSAL",
      "evidence_ids": []
    }
  ],
  "verdict": "CONDITIONAL"
}
